676	// ReadAgentTypeFromTree reads the agent type from a checkpoint's metadata.json file in a git tree.
677	// If metadata.json doesn't exist (shadow branches), it falls back to detecting the agent
678	// from the presence of agent-specific config files (.gemini/settings.json or .claude/).
679	// Returns agent.AgentTypeUnknown if the agent type cannot be determined.
680	func ReadAgentTypeFromTree(tree *object.Tree, checkpointPath string) types.AgentType {
681		// First, try to read from metadata.json (present in condensed/committed checkpoints)
682		metadataPath := checkpointPath + "/" + paths.MetadataFileName
683		if file, err := tree.File(metadataPath); err == nil {
684			if content, err := file.Contents(); err == nil {
685				var metadata checkpoint.CommittedMetadata
686				if err := json.Unmarshal([]byte(content), &metadata); err == nil && metadata.Agent != "" {
687					return metadata.Agent
688				}
689			}
690		}
691	
692		// Fall back to detecting agent from config files (shadow branches don't have metadata.json).
693		// Order: Gemini (most specific check), Claude (established default), OpenCode (newest/preview).
694		if _, err := tree.File(".gemini/settings.json"); err == nil {
695			return agent.AgentTypeGemini
696		}
697		if _, err := tree.Tree(".claude"); err == nil {
698			return agent.AgentTypeClaudeCode
699		}
700		// OpenCode: .opencode directory or opencode.json config
701		if _, err := tree.Tree(".opencode"); err == nil {
702			return agent.AgentTypeOpenCode
703		}
704		if _, err := tree.File("opencode.json"); err == nil {
705			return agent.AgentTypeOpenCode
706		}
707	
708		return agent.AgentTypeUnknown
709	}
