24	// InstallHooks installs Codex hooks in .codex/hooks.json.
25	func (c *CodexAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
26		repoRoot, err := paths.WorktreeRoot(ctx)
27		if err != nil {
28			repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests)
29			if err != nil {
30				return 0, fmt.Errorf("failed to get current directory: %w", err)
31			}
32		}
33	
34		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
35	
36		// Read existing hooks.json if present
37		var rawHooks map[string]json.RawMessage
38		existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
39		if readErr == nil {
40			var hooksFile map[string]json.RawMessage
41			if err := json.Unmarshal(existingData, &hooksFile); err != nil {
42				return 0, fmt.Errorf("failed to parse existing hooks.json: %w", err)
43			}
44			if hooksRaw, ok := hooksFile["hooks"]; ok {
45				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
46					return 0, fmt.Errorf("failed to parse hooks in hooks.json: %w", err)
47				}
48			}
49		}
50	
51		if rawHooks == nil {
52			rawHooks = make(map[string]json.RawMessage)
53		}
54	
55		// Parse event types we manage
56		var sessionStart, userPromptSubmit, stop []MatcherGroup
57		if err := parseHookType(rawHooks, "SessionStart", &sessionStart); err != nil {
58			return 0, err
59		}
60		if err := parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit); err != nil {
61			return 0, err
62		}
63		if err := parseHookType(rawHooks, "Stop", &stop); err != nil {
64			return 0, err
65		}
66	
67		if force {
68			sessionStart = removeEntireHooks(sessionStart)
69			userPromptSubmit = removeEntireHooks(userPromptSubmit)
70			stop = removeEntireHooks(stop)
71		}
72	
73		// Build hook commands
74		var cmdPrefix string
75		if localDev {
76			cmdPrefix = `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go hooks codex `
77		} else {
78			cmdPrefix = "entire hooks codex "
79		}
80		sessionStartCmd := cmdPrefix + "session-start"
81		userPromptSubmitCmd := cmdPrefix + "user-prompt-submit"
82		stopCmd := cmdPrefix + "stop"
83	
84		count := 0
85	
86		if !hookCommandExists(sessionStart, sessionStartCmd) {
87			sessionStart = addHook(sessionStart, sessionStartCmd)
88			count++
89		}
90		if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
91			userPromptSubmit = addHook(userPromptSubmit, userPromptSubmitCmd)
92			count++
93		}
94		if !hookCommandExists(stop, stopCmd) {
95			stop = addHook(stop, stopCmd)
96			count++
97		}
98	
99		if count == 0 {
100			// Still ensure the feature flag is configured even if hooks
101			// were already present (e.g., manually installed).
102			if err := ensureProjectFeatureEnabled(repoRoot); err != nil {
103				return 0, fmt.Errorf("failed to enable codex_hooks feature: %w", err)
104			}
105			return 0, nil
106		}
107	
108		// Marshal modified types back
109		marshalHookType(rawHooks, "SessionStart", sessionStart)
110		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
111		marshalHookType(rawHooks, "Stop", stop)
112	
113		// Preserve existing top-level keys (e.g., $schema) by reusing the parsed file
114		topLevel := make(map[string]json.RawMessage)
115		if readErr == nil {
116			// Re-parse the original file to preserve all top-level keys
117			_ = json.Unmarshal(existingData, &topLevel) //nolint:errcheck // best-effort preservation
118		}
119		hooksJSON, err := json.Marshal(rawHooks)
120		if err != nil {
121			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
122		}
123		topLevel["hooks"] = hooksJSON
124	
125		// Write to file
126		if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
127			return 0, fmt.Errorf("failed to create .codex directory: %w", err)
128		}
129	
130		output, err := jsonutil.MarshalIndentWithNewline(topLevel, "", "  ")
131		if err != nil {
132			return 0, fmt.Errorf("failed to marshal hooks.json: %w", err)
133		}
134	
135		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
136			return 0, fmt.Errorf("failed to write hooks.json: %w", err)
137		}
138	
139		// Enable the codex_hooks feature in the project-level .codex/config.toml.
140		// This keeps the feature flag per-repo rather than global.
141		if err := ensureProjectFeatureEnabled(repoRoot); err != nil {
142			return count, fmt.Errorf("failed to enable codex_hooks feature: %w", err)
143		}
144	
145		return count, nil
146	}
