148	// UninstallHooks removes Entire hooks from Codex hooks.json.
149	func (c *CodexAgent) UninstallHooks(ctx context.Context) error {
150		repoRoot, err := paths.WorktreeRoot(ctx)
151		if err != nil {
152			repoRoot = "."
153		}
154	
155		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
156		data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
157		if err != nil {
158			return nil //nolint:nilerr // No hooks.json means nothing to uninstall
159		}
160	
161		var topLevel map[string]json.RawMessage
162		if err := json.Unmarshal(data, &topLevel); err != nil {
163			return fmt.Errorf("failed to parse hooks.json: %w", err)
164		}
165	
166		var rawHooks map[string]json.RawMessage
167		if hooksRaw, ok := topLevel["hooks"]; ok {
168			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
169				return fmt.Errorf("failed to parse hooks: %w", err)
170			}
171		}
172		if rawHooks == nil {
173			return nil
174		}
175	
176		var sessionStart, userPromptSubmit, stop []MatcherGroup
177		if err := parseHookType(rawHooks, "SessionStart", &sessionStart); err != nil {
178			return err
179		}
180		if err := parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit); err != nil {
181			return err
182		}
183		if err := parseHookType(rawHooks, "Stop", &stop); err != nil {
184			return err
185		}
186	
187		sessionStart = removeEntireHooks(sessionStart)
188		userPromptSubmit = removeEntireHooks(userPromptSubmit)
189		stop = removeEntireHooks(stop)
190	
191		marshalHookType(rawHooks, "SessionStart", sessionStart)
192		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
193		marshalHookType(rawHooks, "Stop", stop)
194	
195		if len(rawHooks) > 0 {
196			hooksJSON, err := json.Marshal(rawHooks)
197			if err != nil {
198				return fmt.Errorf("failed to marshal hooks: %w", err)
199			}
200			topLevel["hooks"] = hooksJSON
201		} else {
202			delete(topLevel, "hooks")
203		}
204	
205		output, err := jsonutil.MarshalIndentWithNewline(topLevel, "", "  ")
206		if err != nil {
207			return fmt.Errorf("failed to marshal hooks.json: %w", err)
208		}
209		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
210			return fmt.Errorf("failed to write hooks.json: %w", err)
211		}
212		return nil
213	}
