215	// AreHooksInstalled checks if Entire hooks are installed in Codex hooks.json.
216	func (c *CodexAgent) AreHooksInstalled(ctx context.Context) bool {
217		repoRoot, err := paths.WorktreeRoot(ctx)
218		if err != nil {
219			repoRoot = "."
220		}
221	
222		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
223		data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
224		if err != nil {
225			return false
226		}
227	
228		var hooksFile HooksFile
229		if err := json.Unmarshal(data, &hooksFile); err != nil {
230			return false
231		}
232	
233		return hasEntireHook(hooksFile.Hooks.SessionStart) &&
234			hasEntireHook(hooksFile.Hooks.UserPromptSubmit) &&
235			hasEntireHook(hooksFile.Hooks.Stop)
236	}
