240	func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]MatcherGroup) error {
241		if data, ok := rawHooks[hookType]; ok {
242			if err := json.Unmarshal(data, target); err != nil {
243				return fmt.Errorf("failed to parse %s hooks: %w", hookType, err)
244			}
245		}
246		return nil
247	}
248	
249	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, groups []MatcherGroup) {
250		if len(groups) == 0 {
251			delete(rawHooks, hookType)
252			return
253		}
254		data, err := json.Marshal(groups)
255		if err != nil {
256			return
257		}
258		rawHooks[hookType] = data
259	}
260	
261	func hookCommandExists(groups []MatcherGroup, command string) bool {
262		for _, group := range groups {
263			for _, hook := range group.Hooks {
264				if hook.Command == command {
265					return true
266				}
267			}
268		}
269		return false
270	}
271	
272	func addHook(groups []MatcherGroup, command string) []MatcherGroup {
273		entry := HookEntry{
274			Type:    "command",
275			Command: command,
276			Timeout: 30,
277		}
278	
279		// Add to an existing group with null matcher, or create a new one
280		for i, group := range groups {
281			if group.Matcher == nil {
282				groups[i].Hooks = append(groups[i].Hooks, entry)
283				return groups
284			}
285		}
286		return append(groups, MatcherGroup{
287			Matcher: nil,
288			Hooks:   []HookEntry{entry},
289		})
290	}
