312	func removeEntireHooks(groups []MatcherGroup) []MatcherGroup {
313		result := make([]MatcherGroup, 0, len(groups))
314		for _, group := range groups {
315			filtered := make([]HookEntry, 0, len(group.Hooks))
316			for _, hook := range group.Hooks {
317				if !isEntireHook(hook.Command) {
318					filtered = append(filtered, hook)
319				}
320			}
321			if len(filtered) > 0 {
322				group.Hooks = filtered
323				result = append(result, group)
324			}
325		}
326		return result
327	}
