40	// LoadSessionState loads the session state for the given session ID.
41	// Returns (nil, nil) when session file doesn't exist or session is stale (not an error condition).
42	// Stale sessions are automatically deleted by the underlying StateStore.
43	func LoadSessionState(ctx context.Context, sessionID string) (*SessionState, error) {
44		store, err := session.NewStateStore(ctx)
45		if err != nil {
46			return nil, fmt.Errorf("failed to create state store: %w", err)
47		}
48	
49		state, err := store.Load(ctx, sessionID)
50		if err != nil {
51			return nil, fmt.Errorf("failed to load session state: %w", err)
52		}
53		return state, nil
54	}
