93	// Normalize an agent string to try matching against known IDs.
94	// Handles variations like "Claude Code", "claude-code", "open code",
95	// "open-code", "OpenCode", "copilot cli", "Gemini CLI", etc.
96	function normalizeAgentId(id: string): AgentId | null {
97	  const lower = id.trim().toLowerCase();
98	
99	  // Direct lowercase match (e.g. "claude", "opencode", "copilot")
100	  if (lower in agents) return lower as AgentId;
101	
102	  // Collapse separators first (e.g. "open code" / "open-code" -> "opencode")
103	  const collapsed = lower.replace(/[- ]/g, "");
104	  if (collapsed in agents) return collapsed as AgentId;
105	
106	  // Strip common suffixes: " code", "-code", " cli", "-cli"
107	  const stripped = lower.replace(/[- ](code|cli)$/, "");
108	  if (stripped in agents) return stripped as AgentId;
109	
110	  // Strip suffixes then collapse (e.g. "Open Code CLI" -> "open code" -> "opencode")
111	  const strippedCollapsed = stripped.replace(/[- ]/g, "");
112	  if (strippedCollapsed in agents) return strippedCollapsed as AgentId;
113	
114	  // Handle "Factory AI Droid" and variations
115	  if (collapsed.includes("factoryaidroid")) return "droid";
116	
117	  return null;
118	}
