120	export function getAgent(id: string | null | undefined): AgentConfig {
121	  if (!id) return agents.unknown;
122	  if (id in agents) return agents[id as AgentId];
123	  if (id in evalAgents) return evalAgents[id];
124	  const normalized = normalizeAgentId(id);
125	  return normalized ? agents[normalized] : agents.unknown;
126	}
127	
128	// Check if an agent string matches a known agent ID
129	export function isKnownAgent(id: string | null | undefined): id is string {
130	  if (!id) return false;
131	  if (id in agents) return true;
132	  return normalizeAgentId(id) !== null;
133	}
134	
135	export function getAgentId(id: string | null | undefined): AgentId {
136	  if (!id) return "unknown";
137	  if (id in agents) return id as AgentId;
138	  return normalizeAgentId(id) ?? "unknown";
139	}
